import java.util.*;

class Solution {
  List<Integer>[] g;
  int[] bobTime, amount;
  int best = Integer.MIN_VALUE;

  public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
    this.amount = amount;
    int n = amount.length;
    g = new ArrayList[n];
    for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(e[1]);
      g[e[1]].add(e[0]);
    }
    bobTime = new int[n];
    Arrays.fill(bobTime, n + 1);
    findBob(bob, -1, 0);
    dfs(0, -1, 0, 0);
    return best;
  }

  boolean findBob(int u, int p, int t) {
    if (u == 0) {
      bobTime[u] = t;
      return true;
    }
    for (int v : g[u])
      if (v != p && findBob(v, u, t + 1)) {
        bobTime[u] = t;
        return true;
      }
    return false;
  }

  void dfs(int u, int p, int t, int score) {
    int gain = t < bobTime[u] ? amount[u] : t == bobTime[u] ? amount[u] / 2 : 0;
    score += gain;
    boolean leaf = u != 0 && g[u].size() == 1;
    if (leaf) best = Math.max(best, score);
    for (int v : g[u]) if (v != p) dfs(v, u, t + 1, score);
  }
}
